create extension if not exists pgcrypto;
create type listing_type as enum ('Apartment','House','Land','Commercial');
create type listing_status as enum ('draft','published','sold','rented');
create type user_role as enum ('buyer','owner','agent','admin');
create table if not exists profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role user_role default 'buyer', avatar_url text, created_at timestamptz default now());
create table if not exists listings (id uuid primary key default gen_random_uuid(), owner_id uuid not null references profiles(id) on delete cascade, title text not null, description text, listing_type listing_type not null, status listing_status default 'published', transaction_type text not null check(transaction_type in ('sale','rent')), price numeric not null check(price>=0), city text not null, neighborhood text, address text, latitude double precision, longitude double precision, bedrooms int default 0, bathrooms numeric default 0, area_m2 numeric not null check(area_m2>0), year_built int, amenities text[] default '{}', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists listing_images (id uuid primary key default gen_random_uuid(), listing_id uuid not null references listings(id) on delete cascade, storage_path text not null, sort_order int default 0, created_at timestamptz default now());
create table if not exists favorites (user_id uuid references profiles(id) on delete cascade, listing_id uuid references listings(id) on delete cascade, created_at timestamptz default now(), primary key(user_id,listing_id));
create table if not exists inquiries (id uuid primary key default gen_random_uuid(), listing_id uuid references listings(id) on delete cascade, sender_id uuid references profiles(id) on delete cascade, message text not null, created_at timestamptz default now());
create table if not exists viewing_requests (id uuid primary key default gen_random_uuid(), listing_id uuid references listings(id) on delete cascade, requester_id uuid references profiles(id) on delete cascade, requested_at timestamptz not null, status text default 'pending' check(status in ('pending','confirmed','declined','cancelled')), created_at timestamptz default now());
create index if not exists listings_city_idx on listings(city); create index if not exists listings_price_idx on listings(price); create index if not exists listings_type_idx on listings(listing_type);
alter table profiles enable row level security; alter table listings enable row level security; alter table listing_images enable row level security; alter table favorites enable row level security; alter table inquiries enable row level security; alter table viewing_requests enable row level security;
create policy "published listings readable" on listings for select using (status='published' or owner_id=auth.uid());
create policy "owners manage listings" on listings for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "listing images readable" on listing_images for select using (exists(select 1 from listings l where l.id=listing_id and (l.status='published' or l.owner_id=auth.uid())));
create policy "users manage favorites" on favorites for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "users send inquiries" on inquiries for insert with check (sender_id=auth.uid());
create policy "users view own inquiries" on inquiries for select using (sender_id=auth.uid() or exists(select 1 from listings l where l.id=listing_id and l.owner_id=auth.uid()));
create policy "users manage viewing requests" on viewing_requests for all using (requester_id=auth.uid() or exists(select 1 from listings l where l.id=listing_id and l.owner_id=auth.uid()));
